VREF = 0.325
MAX_CURRENT = 10.0

class TMC5160CurrentHelper:

    def __init__(self, config, mcu_tmc):
        self.printer = config.get_printer()
        self.name = config.get_name().split()[-1]
        self.mcu_tmc = mcu_tmc
        self.fields = mcu_tmc.get_fields()
        run_current = config.getfloat("run_current", above=0.0,
          maxval=MAX_CURRENT)
        hold_current = config.getfloat("hold_current", MAX_CURRENT, above=0.0,
          maxval=MAX_CURRENT)
        self.req_hold_current = hold_current
        self.sense_resistor = config.getfloat("sense_resistor", 0.075, above=0.0)
        gscaler, irun, ihold = self._calc_current(run_current, hold_current)
        self.fields.set_field("globalscaler", gscaler)
        self.fields.set_field("ihold", ihold)
        self.fields.set_field("irun", irun)

    def _calc_globalscaler(self, current):
        globalscaler = int(current * 256.0 * math.sqrt(2.0) * self.sense_resistor / VREF + 0.5)
        globalscaler = max(32, globalscaler)
        if globalscaler >= 256:
            globalscaler = 0
        return globalscaler

    def _calc_current_bits(self, current, globalscaler):
        if not globalscaler:
            globalscaler = 256
        cs = int(current * 256.0 * 32.0 * math.sqrt(2.0) * self.sense_resistor / (globalscaler * VREF) - 1.0 + 0.5)
        return max(0, min(31, cs))

    def _calc_current(self, run_current, hold_current):
        gscaler = self._calc_globalscaler(run_current)
        irun = self._calc_current_bits(run_current, gscaler)
        ihold = self._calc_current_bits(min(hold_current, run_current), gscaler)
        return (
         gscaler, irun, ihold)

    def _calc_current_from_field(self, field_name):
        globalscaler = self.fields.get_field("globalscaler")
        if not globalscaler:
            globalscaler = 256
        bits = self.fields.get_field(field_name)
        return globalscaler * (bits + 1) * VREF / (8192.0 * math.sqrt(2.0) * self.sense_resistor)

    def get_current(self):
        run_current = self._calc_current_from_field("irun")
        hold_current = self._calc_current_from_field("ihold")
        return (
         run_current, hold_current, self.req_hold_current, MAX_CURRENT)

    def set_current(self, run_current, hold_current, print_time):
        self.req_hold_current = hold_current
        (gscaler, irun, ihold) = self._calc_current(run_current, hold_current)
        val = self.fields.set_field("globalscaler", gscaler)
        self.mcu_tmc.set_register("GLOBALSCALER", val, print_time)
        self.fields.set_field("ihold", ihold)
        val = self.fields.set_field("irun", irun)
        self.mcu_tmc.set_register("IHOLD_IRUN", val, print_time)


class TMC5160:

    def __init__(self, config):
        self.fields = tmc.FieldHelper(Fields, SignedFields, FieldFormatters)
        self.mcu_tmc = tmc2130.MCU_TMC_SPI(config, Registers, self.fields, TMC_FREQUENCY)
        tmc.TMCVirtualPinHelper(config, self.mcu_tmc)
        current_helper = TMC5160CurrentHelper(config, self.mcu_tmc)
        cmdhelper = tmc.TMCCommandHelper(config, self.mcu_tmc, current_helper)
        cmdhelper.setup_register_dump(ReadRegisters)
        self.get_phase_offset = cmdhelper.get_phase_offset
        self.get_status = cmdhelper.get_status
        tmc.TMCWaveTableHelper(config, self.mcu_tmc)
        tmc.TMCStealthchopHelper(config, self.mcu_tmc)
        tmc.TMCVcoolthrsHelper(config, self.mcu_tmc)
        tmc.TMCVhighHelper(config, self.mcu_tmc)
        set_config_field = self.fields.set_config_field
        set_config_field(config, "multistep_filt", True)
        set_config_field(config, "toff", 3)
        set_config_field(config, "hstrt", 5)
        set_config_field(config, "hend", 2)
        set_config_field(config, "fd3", 0)
        set_config_field(config, "disfdcc", 0)
        set_config_field(config, "chm", 0)
        set_config_field(config, "tbl", 2)
